'use strict';
Object.assign(TRANSLATIONS.en,{'导入校验通过':'Import Validated','尚未保存草稿或增加库存':'No Draft Saved or Inventory Posted','识别记录':'Detected Bundles','合计片数':'Total Sheets','生产批次数':'Production Batches','识别工作表':'Detected Worksheet','表头行':'Header Row','入库时间（卢本巴希）':'Inbound Time (Lubumbashi)','捆包预览':'Bundle Preview'});
Business.drawReceiptImportPreview=function(result){const rows=result.lines,cell=v=>`<td data-no-i18n>${esc(v??'')}</td>`,batch=l=>BundleNumber.batch(l.bundle_no),date=value=>{const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Lubumbashi',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(value)).map(x=>[x.type,x.value]));return `${p.year}/${p.month}/${p.day} ${p.hour}:${p.minute}`;};
 $('v26-import-result').innerHTML=`<header class="import-preview-heading"><div><h2>导入校验通过</h2><p>尚未保存草稿或增加库存</p></div></header><div class="import-preview-metrics">${[['识别记录',rows.length],['合计片数',rows.reduce((n,l)=>n+Number(l.sheets_per_bundle),0)],['生产批次数',new Set(rows.map(batch)).size]].map(([label,value])=>`<article><span>${label}</span><strong data-no-i18n>${value.toLocaleString()}</strong></article>`).join('')}</div><p class="import-preview-source"><span>识别工作表</span>：<strong data-no-i18n>${esc(result.mapping?.sheet||'')}</strong><span>表头行</span>：<strong data-no-i18n>${result.mapping?.header_row||1}</strong></p><div class="import-preview-table" tabindex="0" aria-label="捆包预览"><table><thead><tr>${['序号','捆包编号','生产批次','捆包片数','生产日期','入库时间（卢本巴希）','备注'].map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${rows.map((l,i)=>'<tr>'+cell(i+1)+cell(l.bundle_no)+cell(batch(l))+cell(l.sheets_per_bundle)+cell(l.production_date.replaceAll('-','/'))+cell(date(l.inbound_at))+cell(l.remark)+'</tr>').join('')}</tbody></table></div>`;
 I18n.pattern=new RegExp(Object.keys(TRANSLATIONS.en).filter(Boolean).sort((a,b)=>b.length-a.length).map(s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g');I18n.apply();
};
